    STATUS_COMPACT_BELOW = "Kompakte Minikarte: Im Bearbeitungsmodus steht das Kästchen unter der Minikarte – dann baut ezMap nichts um, Blizzards Lage bleibt.",
    OPT_minimapCompact = "Kompakte Minikarte (Kästchen unten, Koordinaten darin)",
    OPT_minimapCompact_TIP = "Das bringt dir: Blizzards Kästchen mit Ortsname, Koordinaten und Uhr („Auberdine 38.6, 43.0 18:07“) steht am unteren Rand des Rings, die Minikarte rückt nach oben an seinen Platz. Die Lupe (Aufspüren) und der Kalender sitzen rund wie Blizzards Knöpfe auf dem Ring, das Addon-Fach rechts vom Kalender. Das Kästchen wird für die Koordinaten etwas breiter; ob sie erscheinen, stellst du weiter in Blizzards Einstellungen ein. Mit ezPanel: Beim Einschalten rücken dessen Bausteine „Ort“ und „Uhr“ rechts an die Leiste, und solange beide dort stehen, ist Blizzards Kästchen verborgen. Gilt nur, solange das Kästchen im Bearbeitungsmodus über der Minikarte steht; wechselt erst nach dem Kampf. Mit ezPanel: Ist dort „Platz oben für die Leiste“ aus, rückt die Minikarte nur bis unter die Leiste. Aus: alles wieder an Blizzards Platz. Läuft SexyMap, gestaltet das die Minikarte.",
    OPT_minimapSquare = "Eckige Minikarte (mehr Fläche)",
    OPT_minimapSquare_TIP = "Das bringt dir: Weiter als Stufe 0 zoomt das Spiel nicht, aber die Minikarte ist eigentlich ein Quadrat – Blizzards runde Maske schneidet die Ecken ab. Eckig siehst du bei derselben Stufe rund 27 % mehr Fläche. Blizzards runder Rahmen wird dafür durch einen schlichten ersetzt; Lage und Größe bleiben. Wechselt erst nach dem Kampf. Läuft SexyMap, gestaltet das die Minikarte.",
    STATUS_ZOOM = "Minikarte: %s Von selbst herauszoomen: aus.",
    STATUS_ZOOM_AUTO = "Minikarte: %s Zoomt nach %d |4Sekunde:Sekunden; von selbst heraus.",
    STATUS_ZOOM_OTHER = "Minikarte: %s Von selbst heraus zoomt %s, deshalb ezMap nicht.",
    OPT_HEADER_MINIMAP = "Minikarte",
    OPT_HEADER_MINIMAP_TIP = "Weiter als Stufe 0 (Mausrad bzw. Blizzards Minus ganz heraus) zoomt das Spiel nicht. Größer stellen zeigt dieselbe Fläche nur größer; mehr Fläche bringt die eckige Minikarte (die Ecken kommen dazu). Ziele für die Markierung stehen im Menü „Aufspüren“ der Minikarte.",
    OPT_minimapAutoZoomDelay = "Von selbst wieder herauszoomen",
    OPT_minimapAutoZoomDelay_TIP = "Das bringt dir: Nach dem Hineinzoomen (Mausrad, Plus) springt die Minikarte nach so vielen Sekunden von selbst auf die weiteste Stufe zurück. Ganz links („aus“) bleibt sie, wie du sie gezoomt hast (ab Werk). Liegt die Maus noch auf der Minikarte, wartet ezMap. Macht das schon ein anderes Addon (z. B. SexyMap), hält sich ezMap zurück. Derselbe Schalter steht als Haken im Menü „Aufspüren“ der Minikarte; er merkt sich die zuletzt gewählte Zeit.",

    -- Einstellungen
    OPT_ENTER = "Wegpunkt setzen",
    OPT_ENTER_BUTTON = "Koordinaten",
    OPT_ENTER_TIP = "Öffnet ein Eingabefeld für Koordinaten in deiner Zone (wie /way). Davor darf ein Zonenname stehen, dahinter ein Name für die Markierung.",
    OPT_HEADER_WAY = "Wegpunkte",
    OPT_wayTrack = "Zielverfolgung einschalten",
    OPT_wayTrack_TIP = "Ab Werk aus, weil es ohne deinen Klick Blizzards Zielverfolgung umstellt. An: Setzt ezMap eine Markierung, führen dich Blizzards Pfeil und die Entfernung am Bildschirmrand hin, ohne dass du sie auf der Karte erst anklicken musst – auch beim Weiterrücken einer Sammel-Route oder der Leveling-Route von ezQuest. Im Kampf setzt ezMap nur die Markierung; der Pfeil folgt danach. Aus: ezMap setzt nur die Markierung; den Pfeil schaltest du mit einem Klick auf die Markierung auf Blizzards Weltkarte ein.",
    -- Hinweis an der Weltkarte (ezCores Core.OptInHint, Welle 29, NACH-27)
    OPTIN_wayTrack = "Schaltet beim Setzen einer Markierung – auch beim Weiterrücken einer Sammel-Route oder der Leveling-Route von ezQuest – ohne Klick Blizzards Zielverfolgung (Pfeil und Entfernung) ein. Ohne den Schalter setzt ezMap nur die Markierung; den Pfeil schaltet ein Klick auf die Markierung auf der Weltkarte ein.",
    OPT_waySlash = "Befehl /way",
    OPT_waySlash_TIP = "Das bringt dir: Wegpunkte aus Anleitungen und Kommentaren (/way 45.3 32.1) landen direkt als Blizzards Kartenmarkierung. Hat ein anderes Addon (z. B. TomTom) /way schon, bleibt es dort, und ezMap nutzt /ezway. Wird nach /reload wirksam.",
    OPT_wayAutoClear = "Markierung bei Ankunft entfernen",
    OPT_wayAutoClear_TIP = "Das bringt dir: Erreichst du Blizzards Kartenmarkierung, verschwindet sie nach 3 oder 5 Sekunden samt Pfeil – egal, wer sie gesetzt hat (/way, Kartenmenü, Strg-Klick, Lehrer, Fundorte). „Aus“: die Markierung bleibt stehen, bis du sie selbst entfernst. Gehst du vorher wieder weg (weiter als 20 Yards), bleibt sie. Ankunft heißt: bis auf 10 Yards heran, nachdem du weiter weg warst – eine Markierung an deiner eigenen Stelle (/way hier) bleibt also stehen, solange du dort bist; kommst du später zurück, verschwindet sie wie jede andere. Die Markierung einer Route, der du folgst, bleibt immer. Ohne Kartenposition (manche Instanzen) entfernt ezMap nichts. Quelle: Blizzards Meldung „Ziel erreicht“ bzw. deine Position laut Spiel.",
    OPT_HERE = "Eigene Position",
    OPT_HERE_BUTTON = "Markieren",
    OPT_HERE_TIP = "Setzt die Markierung dorthin, wo du gerade stehst – zum Wiederfinden oder zum Teilen als Link.",
    OPT_CLEAR = "Markierung",
    OPT_CLEAR_BUTTON = "Entfernen",
    OPT_CLEAR_TIP = "Entfernt Blizzards Kartenmarkierung (wie /way weg).",
    OPT_HEADER_FLIGHTS = "Flugzeiten",
    OPT_flightTimes = "Flugzeit im Tooltip",
    OPT_flightTimes_TIP = "Das bringt dir: Du siehst auf der Flugkarte vor dem Abflug, wie lange der Flug dauert. ezMap lernt jede Strecke beim ersten Flug; bis dahin steht dort „noch unbekannt“. Zeigt Leatrix Plus oder InFlight schon Flugzeiten, hält sich ezMap zurück.",
    OPT_flightBar = "Leiste während des Flugs",
    OPT_flightBar_TIP = "Das bringt dir: Du weißt beim Fliegen, wann du ankommst. Eine Leiste im Stil von Blizzards Zauberleiste zeigt Ziel und Restzeit (Standard oben in der Mitte, angedockt unter Blizzards Atemleiste; verschiebbar im Bearbeitungsmodus oder mit „Teile verschieben“ unter Allgemein); das Kreuz rechts daneben (oder ein Rechtsklick) blendet sie für diesen Flug aus.",
    OPT_PREVIEW = "Vorschau",
    OPT_PREVIEW_BUTTON = "Zeigen",
    OPT_PREVIEW_TIP = "Zeigt die Flugleiste zehn Sekunden lang mit einer Beispielstrecke.",
