    OPT_STATUS_TIP = "Zeigt, welcher Befehl Wegpunkte setzt, wie viele Flugzeiten und Lehrer ezMap kennt und welchem anderen Addon es den Vortritt lässt (TomTom, Leatrix Plus, InFlight, Questie, Forever Tweaks, Leatrix Maps).",
    OPT_FLIGHT_RESET = "Flugzeiten vergessen",
