    -- Sammel-Fundorte auf der Weltkarte (Gather.lua, SAM-10 bis SAM-16)
    OPT_HEADER_GATHER = "Sammeln",
    OPT_HEADER_GATHER_TIP = "Deine eigenen Fundorte von Kräutern, Erzen, Angelplätzen und Kisten auf Blizzards Weltkarte. ezCore merkt sich jede eigene Ernte; vorgefüllte Daten gibt es nicht – die Karte füllt sich beim Sammeln. Die Arten selbst stehen oben im Baum „Karte: was zeigen“ (Gruppe „Sammeln“, Kisten unter „Entdecker-Wissen“) und genauso im ezMap-Knopf der Weltkarte („Sammel-Fundorte“).",
    OPT_gatherHerb = "Kräuter",
    OPT_gatherHerb_TIP = "Fundorte von Kräutern auf der Weltkarte zeigen. Wann genau (immer, mit Beruf, bei aktiver Suche, nie), stellst du darunter bei „Wann zeigen“ ein. Ausgeblendetes merkt ezCore trotzdem weiter.",
    OPT_gatherOre = "Erze",
    OPT_gatherOre_TIP = "Fundorte von Erzvorkommen auf der Weltkarte zeigen. Wann genau (immer, mit Beruf, bei aktiver Suche, nie), stellst du darunter bei „Wann zeigen“ ein. Ausgeblendetes merkt ezCore trotzdem weiter.",
    OPT_gatherFish = "Angelplätze",
    OPT_gatherFish_TIP = "Stellen, an denen du schon geangelt hast, auf der Weltkarte zeigen (je Gewässer und Gebiet). Ausgeblendetes merkt ezCore trotzdem weiter.",
    OPT_gatherChest = "Kisten",
    OPT_gatherChest_TIP = "Kisten und Truhen, die du schon geöffnet hast, auf der Weltkarte zeigen. Das ist Entdecker-Wissen und deshalb ab Werk aus – ein Haken hier ist dein ausdrücklicher Wunsch, auch ohne „Entdecker-Wissen“ in den ezCollection-Einstellungen.",
    OPT_gatherMode = "%s: wann zeigen",
    OPT_gatherMode_TIP = "Wann ezMap die Fundorte der Art %s auf der Weltkarte zeigt: immer, nur mit dem passenden Beruf oder nur während die passende Suche im Menü „Aufspüren“ läuft. Ganz ausblenden: den Haken der Art im Baum „Karte: was zeigen“ oder im Kartenmenü abwählen. Gespeichert in ezCore, damit die Minikarte dieselbe Regel nutzen kann.",
    OPT_gatherSize = "Größe der Fundorte",
    OPT_gatherSize_TIP = "So groß (in Bildpunkten auf dem Bildschirm) zeichnet ezMap die Fundorte auf der Weltkarte – bei jeder Zoomstufe gleich.",
    OPT_gatherAlpha = "Deckkraft der Fundorte",
    OPT_gatherAlpha_TIP = "Wie deckend die Fundorte auf der Weltkarte erscheinen. Weniger lässt Blizzards Kartenbild durchscheinen.",
    OPT_gatherDim = "Eben Geerntetes abdunkeln",
    OPT_gatherDim_TIP = "So viele Minuten nach einer Ernte zeichnet ezMap diese Stelle dunkler – dort wächst noch nichts nach. 0 schaltet das Abdunkeln aus. Die Liste kommt aus ezCore und gilt nur für diese Sitzung.",
    OPT_gatherOverride = "Fundorte trotz GatherMate2/Gatherer zeigen",
    OPT_gatherOverride_TIP = "Läuft GatherMate2 oder Gatherer Reforged, zeichnet ezMap ab Werk keine eigenen Fundorte (sonst stünde jeder Punkt doppelt da); ezCore zählt still weiter. Mit diesem Haken zeigt ezMap seine Fundorte trotzdem.",
    GMAP_MENU = "Sammel-Fundorte",
    GMAP_MENU_TIP = "Alles zu deinen Sammel-Fundorten: welche Arten ezMap auf der Weltkarte und der Minikarte zeigt, wann, welche einzelnen Vorkommen, nach Farbe, dazu Route und „Wo am dichtesten?“. Dieselben Schalter stehen in den Einstellungen im Baum „Karte: was zeigen“.",
    GMAP_IN_FILTER = "Sammel-Fundorte: im Kartenfilter",
    GMAP_IN_FILTER_TIP = "Die Schalter für deine Sammel-Fundorte stehen in Blizzards Kartenfilter (Knopf oben rechts an der Navigationsleiste der Weltkarte), Abschnitt „ezMap“, Gruppe „Sammeln“, und in den Einstellungen im Baum „Karte: was zeigen“. So ist es, weil unter „ezMap an der Weltkarte“ „Beides“ gewählt ist; mit „Knopf“ stehen sie wieder hier im ezMap-Knopf.",
    GMAP_WHEN = "Wann zeigen",
    GMAP_WHEN_TIP = "Regel für diese Art auf der Weltkarte. Sie gilt erst, wenn der Haken der Art gesetzt ist.",
