    GMAP_MODE_tracking_TIP = "Nur, während die passende Suche (Kräutersuche bzw. Mineraliensuche) im Menü „Aufspüren“ der Minikarte läuft.",
    GMAP_OBJECTS = "Einzelne Vorkommen auf dieser Karte",
    GMAP_OBJECTS_TIP = "Jedes Vorkommen dieser Art, das du auf der gezeigten Karte schon geerntet hast, mit der Zahl seiner Fundorte. Haken weg blendet es überall aus.",
