    STATUS_RARES_ON = "Seltene Gegner: Hinweis an (Chatzeile, wenn einer in Sicht kommt).",
    STATUS_RARES_OFF = "Seltene Gegner: Hinweis aus.",   -- dahinter der Weg (Core.SettingsPathText)
    STATUS_RARES_OTHER = "Seltene Gegner: %s läuft, deshalb hält sich ezMap zurück. Trotzdem melden:",   -- dahinter der Weg
    STATUS_RARES_ALSO = "Dazu muss auch der Hinweis an sein:",   -- dahinter der Weg zu „Hinweis auf seltene Gegner“
    STATUS_RARES_DESPITE = "(trotz %s – Meldungen können doppelt kommen)",
    OPT_HEADER_RARES = "Seltene Gegner",
    OPT_HEADER_RARES_TIP = "Entdecker-Wissen gibt es nur auf Wunsch, deshalb ist der Hinweis ab Werk aus. ezMap bringt keine Liste seltener Gegner mit: Es meldet nur, was das Spiel gerade selbst zeigt (einen Gegner mit silbernem Drachen in deiner Nähe oder sein Symbol auf Blizzards Minikarte). Auf die Karte zeichnet es nur, wo du selbst einen gesehen hast – und nur mit „Gesehene seltene Gegner auf der Karte“ im Baum „Karte: was zeigen“ (Gruppe „Schätze und Entdecker-Wissen“). Läuft ein Addon, das seltene Gegner selbst meldet (z. B. RareScanner), schweigt ezMap – außer mit „Auch melden, wenn RareScanner o. Ä. läuft“.",
    OPT_rareAlert = "Hinweis auf seltene Gegner",
    OPT_rareAlert_TIP = "Das bringt dir: Du läufst an keinem seltenen Gegner vorbei. Kommt einer in Sicht (Namensplakette, Maus darüber, Ziel oder Symbol auf Blizzards Minikarte), schreibt ezMap eine Chatzeile mit Name, Zone und Koordinaten; im Kartenmenü setzt „Letzter seltener Gegner“ die Markierung dorthin. Während eines Kampfs keine Meldung, je Gegner höchstens alle zehn Minuten. Ab Werk aus.",
    OPT_rareSound = "Ton beim Hinweis",
    OPT_rareOverride = "Auch melden, wenn RareScanner o. Ä. läuft",
    OPT_rareOverride_TIP = "Läuft ein Addon, das seltene Gegner selbst meldet (z. B. RareScanner, SilverDragon, NovaRares oder Tweaks Forever mit eingeschaltetem Hinweis), schweigt ezMap ab Werk – sonst käme jede Meldung doppelt. Bei RareScanner sieht ezMap nur, dass es läuft, nicht dessen eigene Schalter. Dieser Haken wirkt nur zusammen mit „Hinweis auf seltene Gegner“ (Chatzeile) bzw. „Gesehene seltene Gegner auf der Karte“ (Kartensymbole): Dann meldet ezMap trotzdem bzw. zeichnet gemerkte Sichtungen auf die Karte. Das gilt auch, wenn ein Addon seltene Gegner nur auf die Karte zeichnet, ohne sie zu melden (z. B. HandyNotes: WoW Forever): Derselbe Haken bringt ezMaps Kartensymbole zurück.",
    OPT_rareSound_TIP = "Das bringt dir: Du hörst den Hinweis auch, wenn du gerade nicht in den Chat schaust (Blizzards Schlachtzugswarnung, einmal je Meldung). Nur mit „Hinweis auf seltene Gegner“.",
    OPT_RARE_PREVIEW = "Hinweis – Probe",
    OPT_RARE_PREVIEW_TIP = "Schreibt eine Beispielmeldung in den Chat und spielt den Ton – so sieht und klingt der Hinweis.",
    OPT_RARE_LAST = "Letzter seltener Gegner",
    OPT_RARE_LAST_TIP = "Setzt Blizzards Markierung auf den zuletzt gemeldeten seltenen Gegner (wie im Kartenmenü und /ezmap selten).",
    -- Baum der Karte (Tree.lua, Wunsch des Nutzers vom 15.11.2026)
    OPT_HEADER_TREE = "Karte: was zeigen",
    OPT_HEADER_TREE_TIP = "Alles, was ezMap auf Blizzards Weltkarte, auf der Minikarte und in den Kartenmenüs zeigt, als Baum: oben „Alles“, darunter Gruppen, darunter die einzelnen Arten. Eine Gruppe schaltet alles darunter mit; sind die Arten gemischt, steht sie auf „Teilweise“ – wählst du „Teilweise“ wieder, kommt die zuletzt gemischte Auswahl zurück. Jeder Haken bleibt einzeln gemerkt. Dieselbe Gliederung steht im ezMap-Knopf der Weltkarte („Was ezMap auf der Karte zeigt“, Sammeln im eigenen Abschnitt).",
    OPT_tree_all = "Alles von ezMap",
    OPT_tree_all_TIP = "Das bringt dir: Mit einem Griff blendest du alles aus, was ezMap auf Karte, Minikarte und in den Kartenmenüs zeigt – und wieder ein. „Teilweise“ heißt: einiges ist an, einiges aus; wählst du es, kommt deine letzte gemischte Auswahl zurück. Im Kartenmenü schaltet ein Klick alles aus, der nächste bringt den Stand davor zurück; Entdecker-Wissen geht dabei nur an, wenn es vorher an war.",
    OPT_tree_trainers = "Lehrer",
    OPT_tree_trainers_TIP = "Das bringt dir: Du findest deinen Lehrer wieder, wenn neue Ränge warten. Jeder Lehrer, dessen Fenster du öffnest, wird gemerkt (in ezCore, für alle ez-Module); im Kartenmenü und im Menü „Aufspüren“ setzt unter „Lehrer“ ein Klick die Markierung zu ihm. Darunter einzeln: Klassenlehrer, Tierausbilder, Berufslehrer je Beruf, weitere Lehrer. Aus: ezMap bietet keine Lehrer an – gemerkt bleiben sie.",
    OPT_tree_trainerProf = "Berufslehrer",
    OPT_tree_trainerProf_TIP = "Das bringt dir: Berufslehrer einzeln je Beruf ein- und ausblenden. Die Berufe stehen hier, sobald du einen ihrer Lehrer besucht hast (im ezMap-Knopf einzeln; neue Berufe folgen dieser Auswahl).",
    OPT_trainerClass = "Klassenlehrer",
    OPT_trainerClass_TIP = "Das bringt dir: Lehrer deiner Klasse stehen unter „Lehrer“ im Kartenmenü, dazu „Nächster Klassenlehrer“ auf deinem Kontinent. Quelle: Lehrer, deren Fenster du geöffnet hast (ezCore).",
    OPT_trainerPet = "Tierausbilder",
    OPT_trainerPet_TIP = "Das bringt dir: Tierausbilder (Jäger lernen dort die Fähigkeiten ihres Tiers) stehen unter „Lehrer“, für Jäger dazu „Nächster Tierausbilder“. Quelle: besuchte Lehrer (ezCore).",
    OPT_trainerOther = "Weitere Lehrer",
