    OPT_tree_vendors = "Händler",
    OPT_tree_vendors_TIP = "Das bringt dir: Händler, die du in der gezeigten Zone schon angesprochen hast, stehen im Kartenmenü unter „Händler hier“; ein Klick setzt die Markierung. Darunter einzeln: Händler und Händler mit Reparatur. Quelle: besuchte Händler (ezCore).",
    OPT_vendorTargets = "Händler",
