    OPT_repairTargets = "Händler mit Reparatur",
    OPT_repairTargets_TIP = "Das bringt dir: Händler, bei denen du reparieren kannst, als Ziel im Kartenmenü – auch, wenn die übrigen Händler aus sind. Quelle: besuchte Händler (ezCore).",
    OPT_tree_travel = "Reisen und Flugmeister",
    OPT_tree_travel_TIP = "Das bringt dir: Der nächste Flugmeister im Menü „Aufspüren“, der Flugmeister am Ziel deiner Markierung samt gelernter Flugzeit, die Flugzeit im Tooltip der Flugpunkte, die Leiste mit der Restzeit während des Flugs und die Flugpunkte, die dir oder deinen Twinks noch fehlen.",
    OPT_flightNearest = "Nächster Flugmeister",
    OPT_flightNearest_TIP = "Das bringt dir: Im Menü „Aufspüren“ steht der nächste Flugmeister (auch noch nicht entdeckte deiner Fraktion); ein Klick setzt die Markierung. Quelle: Blizzards Flugkarte (C_TaxiMap).",
    OPT_flightDest = "Flugmeister am Ziel",
    OPT_flightDest_TIP = "Das bringt dir: Ist eine Markierung gesetzt, nennen Kartenmenü und Menü „Aufspüren“ den Flugmeister am Ziel und die Flugzeit dorthin, wenn du die Strecke schon geflogen bist („bei dir gemessen“). Kein Routenplaner.",
    -- Flugpunkte, die dir oder deinen Twinks fehlen (Welle 26, F5; FlightNodes.lua)
    OPT_flightMissing = "Fehlende Flugpunkte (auch Twinks)",
    OPT_flightMissing_TIP = "Das bringt dir: Im Kartenmenü steht „Flugpunkte, die dir fehlen“ für den Kontinent der gezeigten Karte, darunter je Twink seine fehlenden; ein Klick setzt Blizzards Markierung. Im Tooltip von Blizzards Flugpunkten auf der Weltkarte steht, welche Twinks ihn noch nicht entdeckt haben. Quelle: welche Flugpunkte es gibt, laut Client-Tabellen (ezCore); was ein Charakter kennt, laut Blizzards Flug- und Weltkarte, gelesen beim Einloggen und am Flugmeister.",
    MENU_TAXI = "Flugpunkte, die dir fehlen",
    MENU_TAXI_COUNT = "Flugpunkte, die dir fehlen (%d)",
    MENU_TAXI_TIP = "Flugpunkte dieses Kontinents für deine Fraktion, die du noch nicht entdeckt hast; ein Klick setzt Blizzards Markierung. Darunter dasselbe je Twink. Quelle: %s",
    MENU_TAXI_UNSEEN = "Noch nicht erfasst",
