    MENU_TAXI_ALL = "Du kennst alle %d Flugpunkte dieses Kontinents",
    MENU_TAXI_ALL_TIP = "Gezählt sind die Flugpunkte deiner Fraktion laut Client-Tabellen (ohne Hilfs- und Quest-Flugpunkte).",
    MENU_TAXI_TWINKS = "Deine Twinks",
