    MENU_TAXI_TWINKS_UNSEEN_TIP = "Für diese Charaktere kennt ezMap die Flugpunkte dieses Kontinents noch nicht. Mit ihnen einmal einloggen (Blizzards Weltkarte sagt es dann) oder hier einen Flugmeister ansprechen: %s",
    TAXI_ENTRY = "%s (%s)",
    TAXI_ENTRY_TIP = "Klick setzt Blizzards Markierung an den Flugpunkt. Quelle: %s",
    TAXI_ENTRY_NOPLACE_TIP = "Die Lage auf einer Karte nennt der Client hier nicht – keine Markierung möglich. Quelle: %s",
