    OPT_tree_dungeons = "Dungeon-Eingänge",
    OPT_tree_dungeons_TIP = "Das bringt dir: Symbole für Dungeon- und Schlachtzug-Eingänge auf der Weltkarte und die Liste der Eingänge im Kartenmenü bzw. im Menü „Aufspüren“. Quelle: zuerst das Spiel, sonst die Eingänge, durch die du selbst gegangen bist.",
    OPT_entranceList = "Eingänge im Kartenmenü",
    OPT_entranceList_TIP = "Das bringt dir: Unter „Dungeoneingänge“ im Kartenmenü und im Menü „Aufspüren“ setzt ein Klick die Markierung zum Eingang – auch dann, wenn ein anderes Addon die Symbole zeichnet. Quelle wie bei den Symbolen.",
    OPT_tree_gather = "Sammeln",
    OPT_tree_gather_TIP = "Das bringt dir: Deine eigenen Fundorte von Kräutern, Erzen und Angelplätzen auf der Weltkarte (Quelle: deine Ernten, gemerkt von ezCore). Darunter einzeln je Art; „Wann zeigen“ und einzelne Vorkommen stehen im ezMap-Knopf unter „Sammel-Fundorte“ an der Art, Größe und Deckkraft unter „Sammeln“.",
    OPT_tree_explorer = "Schätze und Entdecker-Wissen",
    OPT_tree_explorer_TIP = "Das bringt dir: Wissen zum Entdecken – Kisten, Fundorte fehlender Bibliotheksbücher, gesehene seltene Gegner – nur, wenn du es willst (Entdecker-Wissen ist ab Werk aus). Quelle: was du selbst gesehen hast (ezCore), bei Büchern sonst Questie, wenn es läuft.",
    OPT_tree_own = "Eigene Wegpunkte und Kartenhilfen",
    OPT_tree_own_TIP = "Das bringt dir: die zuletzt gesetzten Markierungen im Kartenmenü („Zuletzt“) und die Koordinaten-Zeile auf der Weltkarte.",
    -- Themen des Kartenmenüs (Welle 27, Wunsch des Nutzers vom 16.11.2026: Menüaufteilung, passende Symbole)
    OPT_tree_town = "Dienste in der Stadt",
    OPT_tree_town_TIP = "Das bringt dir: Lehrer, Händler und Rezept-Fundorte an einer Stelle – alles, was du in Städten und Dörfern suchst. Die Symbole sind dieselben wie in Blizzards Menü „Aufspüren“ an der Minikarte (Lehrer, Händler, Reparieren …): Blizzards Liste zeigt diese Dienste auf der Minikarte, ezMap setzt im Kartenmenü die Markierung zu denen, die du besucht hast.",
    OPT_tree_discover = "Entdecken",
    OPT_tree_discover_TIP = "Das bringt dir: Wissen zum Entdecken – Kisten, Bibliotheksbücher, gesehene seltene Gegner und, wenn Questie läuft, Gegner und Objekte laut Questie. Nur auf Wunsch: „Alles von ezMap“ schaltet dieses Thema nicht mit ein. Ein Klick auf „Entdecken“ selbst schaltet Entdecker-Wissen ein; die Gruppe „laut Questie“ braucht ihren eigenen Haken, darin Objekte und seltene Gegner noch einmal je ihren eigenen.",
    OPT_tree_journey = "Reise",
    OPT_tree_journey_TIP = "Das bringt dir: Flugmeister, Flugzeiten, Flugpunkte, die dir oder deinen Twinks fehlen, und Dungeon-Eingänge an einer Stelle.",
