    TREE_ALL_ON_TIP = "Schaltet alle Einträge dieser Gruppe ein. Die Auswahl bleibt gemerkt.",
    TREE_ALL_ON_TIP_SKIP = "Schaltet alle Einträge dieser Gruppe ein, außer %s – das geht nur mit eigenem Haken an (nur auf Wunsch). Die Auswahl bleibt gemerkt.",
    TREE_ALL_OFF_TIP = "Schaltet alle Einträge dieser Gruppe aus. Die Auswahl bleibt gemerkt; ein Klick auf die Gruppe selbst bringt den Stand davor zurück.",
    MSEC_WAY = "Wegpunkte",
    MSEC_SHOW = "Anzeige auf der Karte",
    TRACK_SEC_MINIMAP = "Minikarte",
    TRACK_SEC_TOWN_TIP = "Blizzards Liste oben zeigt diese Dienste auf der Minikarte; ezMap setzt die Markierung zu den Lehrern, die du besucht hast – mit denselben Symbolen wie Blizzards Einträge. Steht Blizzards passender Eintrag oben, steht ezMaps Eintrag direkt darunter; mit „Mit Blizzards Aufspüren gemeinsam schalten“ schalten beide zusammen.",
    OPT_wayRecent = "Zuletzt gesetzte Markierungen",
    OPT_wayRecent_TIP = "Das bringt dir: Unter „Zuletzt“ im Kartenmenü und im Menü „Aufspüren“ setzt ein Klick eine früher gesetzte Markierung wieder (wie /way liste).",
    OPT_mapPlace = "ezMap an der Weltkarte",
    OPT_mapPlace_TIP = "Das bringt dir: alles von ezMap mit einem Klick an der Karte. „Knopf“ (ab Werk): ein runder Knopf neben Blizzards Pin-Knopf – Linksklick öffnet ein Menü in Abschnitten (Wegpunkte, Dienste in der Stadt, Reise, Sammeln, Entdecken, was ezMap auf der Karte zeigt), Rechtsklick die Einstellungen. „Blizzards Kartenfilter“: kein eigener Knopf, ezMaps Schalter stehen im Kartenfilter von Blizzard (Knopf oben rechts an der Weltkarte), Abschnitt „ezMap“. „Beides“: der Knopf und der Abschnitt im Kartenfilter – dann verweist der Knopf für den Baum und die Sammel-Fundorte auf den Kartenfilter.",
    MAP_PLACE_button = "Knopf",
