    TREE_MIXED_TIP = "Gerade gemischt: %d von %d an. Ein Klick schaltet alle darunter aus, noch ein Klick bringt diese Auswahl zurück („Teilweise wiederherstellen“ ebenso).",
    TREE_RESTORE = "Teilweise wiederherstellen",
    TREE_RESTORE_ALL = "Alles: teilweise wiederherstellen",
    TREE_RESTORE_TIP = "Stellt die gemischte Auswahl wieder her, die vor dem letzten Ein- oder Ausschalten der ganzen Gruppe galt.",
    TREE_DYN_NONE = "Noch keine Berufslehrer besucht",
    TREE_DYN_NONE_TIP = "Sobald du das Fenster eines Berufslehrers öffnest, steht sein Beruf hier zum einzelnen Ein- und Ausblenden.",
    TREE_SECTION = "ezMap",
    TREE_SECTION_TIP = "Alles, was ezMap auf dieser Karte, auf der Minikarte und in den Kartenmenüs zeigt – als Baum wie auf der Einstellungsseite („Karte: was zeigen“). Die Schalter sind ezMaps eigene; Blizzards Filter darüber bleiben unberührt.",
    TREE_MENU = "Was ezMap auf der Karte zeigt",
    TREE_MENU_TIP = "Derselbe Baum wie in den Einstellungen („Karte: was zeigen“): Alles, Gruppen und einzelne Arten ein- und ausblenden. Sammeln hat oben einen eigenen Abschnitt („Sammel-Fundorte“).",
    MENU_VENDORS = "Händler hier (%d)",
