    VENDOR_REPAIR_MARK = "(Reparatur)",
    STATUS_TREE = "Karte (Baum): aus: %s; teilweise: %s.",
    STATUS_TREE_NONE = "nichts",
    -- Sammel-Fundorte auf der Minikarte (SAM-11)
    OPT_tree_gatherMini = "Auf der Minikarte",
    OPT_tree_gatherMini_TIP = "Das bringt dir: Deine eigenen Fundorte erscheinen auch auf Blizzards Minikarte, sobald du in Reichweite bist – je Art einzeln, nach der Regel „Wann zeigen“ für die Minikarte (ab Werk Kräuter und Erze nur bei aktiver Suche, Angelplätze nie). Maus darauf zeigt denselben Tooltip wie auf der Weltkarte; ein Klick geht an die Minikarte (Ping). Quelle: deine Ernten (ezCore).",
    OPT_gatherMiniHerb = "Kräuter auf der Minikarte",
    OPT_gatherMiniHerb_TIP = "Das bringt dir: Fundorte von Kräutern, an denen du schon geerntet hast, auf der Minikarte in Reichweite. Wann sie erscheinen, regelt „Wann zeigen“ (ab Werk: bei aktiver Kräutersuche).",
    OPT_gatherMiniOre = "Erze auf der Minikarte",
    OPT_gatherMiniOre_TIP = "Das bringt dir: Fundorte von Erzen, an denen du schon geschürft hast, auf der Minikarte in Reichweite. Wann sie erscheinen, regelt „Wann zeigen“ (ab Werk: bei aktiver Mineraliensuche).",
    OPT_gatherMiniFish = "Angelplätze auf der Minikarte",
    OPT_gatherMiniFish_TIP = "Das bringt dir: Stellen, an denen du schon geangelt hast, auf der Minikarte in Reichweite – ab Werk, sobald du angeln kannst (Regel „Mit Beruf“, umzustellen unter „Wann zeigen“).",
    OPT_tree_gatherColor = "Nach Farbe (Fertigkeitspunkt)",
    OPT_tree_gatherColor_TIP = "Das bringt dir: Nur die Vorkommen, die dir mit der gewählten Wahrscheinlichkeit einen Fertigkeitspunkt geben – auf Weltkarte, Minikarte und in Routen. Die Farbe rechnet ezCollection aus deiner Fertigkeit und dem nötigen Wert des Vorkommens (laut Client-Meldung oder bei dir beobachtet) nach der Faustregel der Sammelberufe: orange bis %ORANGE_TO%, gelb bis %YELLOW_TO%, grün bis %GREEN_TO% Punkte darüber, danach grau. Berechnet, nicht vom Spiel gemeldet. Dieser Filter zählt nicht zu „Sammeln“ und „Alles von ezMap“ und wird von deren Klick nicht mitgeschaltet. Vorkommen, die du noch nicht sammeln kannst (rot), stehen rötlich und blasser da – „Rot – noch nicht abbaubar“ abwählen blendet sie aus. Kisten und Angelplätze siebt die Farbe nicht.",
    OPT_gatherColorOrange = "Orange – Punkt sicher",
    OPT_gatherColorOrange_TIP = "Das bringt dir: Vorkommen, die dir bei jeder Ernte einen Fertigkeitspunkt geben (deine Fertigkeit liegt höchstens %ORANGE_TO% Punkte über dem nötigen Wert; berechnet).",
    OPT_gatherColorYellow = "Gelb – meist ein Punkt",
    OPT_gatherColorYellow_TIP = "Das bringt dir: Vorkommen mit hoher Chance auf einen Fertigkeitspunkt (%YELLOW_FROM% bis %YELLOW_TO% Punkte über dem nötigen Wert; die Chance fällt dabei gleichmäßig von %YELLOW_PCT_FROM% auf etwa %YELLOW_PCT_TO%, der Tooltip am Punkt nennt sie; berechnet).",
    OPT_gatherColorGreen = "Grün – Chance nimmt ab",
    OPT_gatherColorGreen_TIP = "Das bringt dir: Vorkommen, deren Chance auf einen Fertigkeitspunkt weiter fällt (%GREEN_FROM% bis %GREEN_TO% Punkte über dem nötigen Wert; von etwa %GREEN_PCT_FROM% auf etwa %GREEN_PCT_TO%, der Tooltip am Punkt nennt sie; berechnet).",
    OPT_gatherColorGray = "Grau – kein Punkt mehr",
    OPT_gatherColorGray_TIP = "Das bringt dir: Vorkommen, die dir keinen Fertigkeitspunkt mehr geben (%GRAY_FROM% und mehr Punkte über dem nötigen Wert) – nur noch für den Ertrag.",
    OPT_gatherColorRed = "Rot – noch nicht abbaubar",
    OPT_gatherColorRed_TIP = "Das bringt dir: Kräuter und Erze, für die dein Rang laut ezCore noch nicht reicht (laut Client-Meldung oder bei dir beobachtet), oder für die dir der Beruf fehlt – rötlich und blasser, damit du siehst, was später kommt. Abgewählt blendet ezMap sie aus (vorher der Haken „Nur, was ich abbauen kann“). Vorkommen ohne bekannten Rang bleiben sichtbar.",
    OPT_gatherColorUnknown = "Unbekannt",
    OPT_gatherColorUnknown_TIP = "Das bringt dir: Vorkommen, deren nötigen Wert ezCollection noch nicht kennt (es lernt ihn beim Sammeln) oder nur nach oben kennt und der über deiner Fertigkeit liegt, und alle Vorkommen, solange deine eigene Fertigkeit unbekannt ist. Angelplätze siebt dieser Filter nicht (sie verlangen keinen Wert, die Chance hängt am Gebiet) – sie blendest du mit dem Haken „Angelplätze“ aus. Eine weiße Stufe kennt Blizzard bei Fertigkeitspunkten nicht (nur orange, gelb, grün, grau); an ihre Stelle tritt hier „unbekannt“.",
    OPT_gatherMiniChest = "Kisten auf der Minikarte",
    OPT_gatherMiniChest_TIP = "Das bringt dir: Kisten, die du schon geöffnet hast, auf der Minikarte in Reichweite. Entdecker-Wissen: ab Werk aus.",
    OPT_gatherMiniMode = "%s auf der Minikarte: wann zeigen",
    OPT_gatherMiniMode_TIP = "Wann ezMap die Fundorte der Art %s auf der Minikarte zeigt: immer, nur mit dem passenden Beruf oder nur während die passende Suche im Menü „Aufspüren“ läuft. Ganz ausblenden: den Haken der Art abwählen. Gespeichert in ezCore (Fläche Minikarte, getrennt von der Weltkarte).",
    OPT_gatherMiniSize = "Größe auf der Minikarte",
    OPT_gatherMiniSize_TIP = "So groß (in Bildpunkten) zeichnet ezMap die Fundorte auf der Minikarte.",
    OPT_gatherMiniAlpha = "Deckkraft auf der Minikarte",
    OPT_gatherMiniAlpha_TIP = "Wie deckend die Fundorte auf der Minikarte erscheinen. Weniger lässt Blizzards Minikarte durchscheinen.",
    OPT_gatherHideNearYards = "In der Nähe auf der Minikarte ausblenden",
    OPT_gatherHideNearYards_TIP = "Kommst du einem gemerkten Fundort näher als die eingestellte Entfernung (in Yards), verschwindet ezMaps Punkt auf der Minikarte – so verdeckt er Blizzards eigenes Symbol der Suche (Kräutersuche, Mineraliensuche …) nicht, und du siehst, ob das Vorkommen gerade wirklich da ist. Gehst du weiter weg, erscheint der Punkt wieder. Ganz links („aus“) bleiben alle Punkte stehen. Das gilt auch für den großen „nächsten Punkt“ einer Sammel-Route und ihre Punkte an Fundorten; die kleinen Punkte dazwischen zeigen weiter die Richtung. Blizzards Symbol zeigt die Minikarte nur, solange die passende Suche im Menü „Aufspüren“ läuft. Je weiter die Minikarte herangezoomt ist, desto mehr ihrer Fläche liegt in diesem Umkreis. Die Weltkarte bleibt, wie sie ist (dort zeigt Blizzard keine Vorkommen). Quelle der Entfernung: deine Position laut Spiel.",
    GMAP_MINI_SEARCH = "Nur bei aktiver Suche",
    GMAP_MINI_GROUP = "Sammel-Fundorte auf der Minikarte",
    GMAP_MINI_CHEST = "Kisten auf der Minikarte (Entdecker-Wissen)",
    GMAP_MINI_CHEST_NOTE = "Kisten gehören zum Entdecker-Wissen (nur auf Wunsch) und stehen deshalb nicht in der Gruppe „Sammel-Fundorte auf der Minikarte“ – deren Haken schaltet sie nicht mit.",
    GMAP_MINI_SEARCH_TIP = "An: Kräuter und Erze erscheinen auf der Minikarte nur, solange die Kräuter- bzw. Mineraliensuche oben in diesem Menü läuft. Aus: wieder so wie vorher (ohne frühere Wahl: mit dem passenden Beruf). Je Art fein einstellbar unter „Sammel-Fundorte auf der Minikarte“, Untermenü der Art.",
    GMAP_MINI_WHEN_TIP = "Regel für diese Art auf der Minikarte (getrennt von der Weltkarte). Sie gilt erst, wenn der Haken der Art gesetzt ist.",
    GMAP_MINI_UNAVAILABLE_api = "Gerade nicht möglich: Der Client nennt den Sichtradius der Minikarte nicht (C_Minimap.GetViewRadius fehlt), deshalb setzt ezCore dort keine Punkte. Die Fundorte stehen weiter auf der Weltkarte.",
    GMAP_MINI_UNAVAILABLE_nocore = "Gerade nicht möglich: ezCore bringt keine Punkte für die Minikarte mit (zu alt).",
    GMAP_MINI_STATE = "Auf der Minikarte: %d von %d Fundorten in Reichweite",
    GMAP_MINI_OFF = "Minikarte gerade ohne Punkte: %s",
