    OPT_mapCoords = "Coordinates on the map",
    OPT_mapCoords_TIP = "What you get: at the bottom left of the world map you read where you stand and which spot the cursor is over – to find a place from a guide or for /way. If you are not on the map shown, the line says so. If another addon already shows coordinates (e.g. Leatrix Maps), ezMap stays out of the way. The switch is in the map menu too.",
    OPT_pinsRound = "Round point icons",
    OPT_pinsRound_TIP = "What you get: item and spell icons of ezCollection's points on the world map and minimap appear round like Blizzard's portraits instead of as small squares. ezCollection always trims the dark border in the image; Blizzard's own map symbols (atlas) and plain dots stay as they are.",
    OPT_bookTargets = "Library books in the map menu",
    OPT_bookTargets_TIP = "What you get: in the world map's menu, \"Library books\" lists the books this character has not handed in yet, with where to find them in the zone shown – where you picked one up yourself and according to Questie, if it is running. A click sets Blizzard's map pin. Find spots are explorer knowledge, so this is off by default. The switch is in the map menu too.",

    TOUR_MAP_BUTTON = "ezMap: set waypoints here – enter coordinates, pin your position, recent pins, visited trainers and dungeon entrances. A click sets Blizzard's map pin; a click on the pin turns on the arrow to it – or, for every pin, the switch \"Turn on navigation\" (off by default).",
    TOUR_PIN = "Blizzard's map pin: ezMap uses exactly this one. Blizzard shows arrow and distance at the edge of the screen once you follow it (click the pin or ezMap's switch \"Turn on navigation\"). From chat: /way 45 32 or /way Westfall 56 47 (if TomTom has /way, use /ezway).",
    TOUR_TRAINERS = "Trainers: open a trainer's window once and ezMap remembers them. In the menu under \"Trainers\" a click leads to them, \"Nearest class trainer\" to the closest one on your continent.",
