    TOUR_TRACKING = "Tracking: Blizzard's menu now lists ezMap destinations at the bottom – nearest flight master, trainers, dungeon entrances, recent pins. A click sets Blizzard's map pin (the arrow comes with the switch \"Turn on navigation\" or a click on the pin).",
    OPT_trackingMenu = "Destinations in the tracking menu",
    OPT_trackingMenu_TIP = "What you get: Blizzard's tracking menu on the minimap lists the nearest flight master (also undiscovered ones), trainers, dungeon entrances of your zone and recent map pins at the bottom. A click sets Blizzard's map pin (the arrow comes with the switch \"Turn on navigation\" or a click on the pin). The switch \"Zoom out by itself\" is there too.",
    -- Tracking menu: remember the selection, Check All / Uncheck All (user's request of 15.11.2026 evening)
    OPT_trackingRemember = "Remember the tracking menu selection",
    OPT_trackingRemember_TIP = "What you get: ezMap remembers per character which types you tick in Blizzard's tracking menu on the minimap (mailbox, innkeeper, find herbs …) and restores them after logging in, after /reload and after being revived – only what differs, and only after combat. ezMap turns search spells such as Find Herbs and Find Minerals back on only with \"Turn on search spells by itself\" (off by default), otherwise by a click in the tracking menu; if the game allows only one at a time, the one you picked last comes back. Blizzard remembers \"Low-level quests\" itself in its settings.",
    OPT_trackingSpellAuto = "Turn on search spells by itself",
    OPT_trackingSpellAuto_TIP = "Off by default because ezMap switches one of Blizzard's spells without your click. On: after logging in, after /reload, a zone change and being revived ezMap turns the remembered search spell (Find Herbs or Find Minerals) back on by itself – only out of combat. Off: ezMap offers it for a click in the minimap's tracking menu (section \"Minimap\"). If Blizzard blocks turning it on, the box turns off by itself; ticking it again undoes that. The same box is in the tracking menu too.",
    OPTIN_trackingSpellAuto = "Turns your remembered search spell (Find Herbs or Find Minerals) back on without a click after logging in, a zone change and being revived. Without the box ezMap offers it for a click in the minimap's tracking menu.",
    OPTIN_WHERE_trackingSpellAuto = "Setting: ezMap » Minimap, or the box in the minimap's tracking menu (section \"Minimap\").",
    -- Coupling with Blizzard's tracking menu (user's answer of 17.11.2026, "all of it": C)
    OPTIN_trackingCouple = "Switches Blizzard's ticks in the tracking menu along without a click on them when you switch ezMap's matching group – and the other way round.",
    OPT_trackingCouple = "Switch together with Blizzard's tracking",
    OPT_trackingCouple_TIP = "What you get: when you tick or untick \"Class Trainer\", \"Profession Trainer\", \"Repair\" or \"Flight Master\" in Blizzard's tracking menu, ezMap switches its matching group along (class trainers, profession trainers, vendors with repair, nearest flight master) – and the other way round. Applies from the next click on; anything that differed before stays as it is. ezMap switches Blizzard's ticks only outside combat, otherwise right afterwards. Search spells (Find Herbs, Find Minerals) are not switched along because the game often allows only one at a time. Off by default.",
    TRACK_REMEMBER = "Remember the selection above",
    TRACK_REMEMBER_OTHER = "Remembering the selection: done by %s",
    TRACK_CHECK_ALL_ALT = "Tick all",
    TRACK_CHECK_ALL_TIP = "Ticks every type in this list – the counterpart to Blizzard's entry above, which clears every tick (added by ezMap). Search spells such as Find Herbs and Find Minerals stay as they are: the game often allows only one at a time, pick those one by one.",
    TRACK_UNCHECK_ALL_TIP = "Clears every tick in this list, search spells included (added by ezMap – Blizzard shows no entry of its own for this in this view). Quest points, account completed quests and target stay as they are – Blizzard's own entry turns those straight back on. During combat the search spells follow right afterwards.",
    OPT_TRACK_ALL_ON = "Tracking: tick every type",
    OPT_TRACK_ALL_ON_TIP = "Ticks every type in Blizzard's tracking menu on the minimap (like the entry \"Check All\" there). Search spells such as Find Herbs and Find Minerals stay as they are – the game often allows only one at a time.",
    OPT_TRACK_ALL_OFF = "Tracking: clear every tick",
    OPT_TRACK_ALL_OFF_TIP = "Clears every tick in Blizzard's tracking menu on the minimap, search spells included – like Blizzard's own entry at the top of that menu. Quest points, account completed quests and target stay as they are (Blizzard turns those straight back on). During combat the search spells follow right afterwards.",
    TRACKMEM_ALL_ON = "Tracking: ticked %d types.",
    TRACKMEM_ALL_OFF = "Tracking: cleared %d ticks.",
    TRACKMEM_NOTHING = "Tracking: nothing to change.",
    TRACKMEM_SPELLS_SKIPPED = "Tracking: search spells not included (%s) – the game often allows only one at a time. Pick them one by one with a click.",
    TRACKMEM_OFF_WHAT = "Tracking: turning off the search spells",
    TRACKMEM_NOAPI = "Tracking: the client doesn't report the types (C_Minimap is missing).",
    TRACKMEM_BLOCKED = "Blizzard blocked turning on a search spell in the tracking menu. This also applies after your next login: ezMap no longer turns on search spells by itself (the box \"Turn on search spells by itself\" is off now) and offers the remembered one in the minimap's tracking menu for a click (section \"Minimap\"). Ticking it again undoes this.",
    TRACKMEM_BLOCKED_NOMENU = "Blizzard blocked turning on a search spell in the tracking menu. This also applies after your next login: ezMap no longer turns on search spells by itself. Please click Blizzard's own entry in the minimap's tracking menu. If you turn on \"%s\" in ezMap's settings, ezMap offers the remembered one there in the section \"Minimap\"; the box \"Turn on search spells by itself\" (also in ezMap's settings, section \"Minimap\") undoes this.",
