    STATUS_COMPACT_ON = "Compact minimap: box with zone name, coordinates and clock below the minimap, magnifier and calendar round on the ring, addon compartment right of the calendar.",
    STATUS_COMPACT_PANEL = "Compact minimap: location and clock are on ezPanel's bar, Blizzard's box below the minimap is hidden; magnifier and calendar round on the ring, addon compartment right of the calendar.",
