    -- Rare enemies
    RARE_ALERT = "Rare enemy: %s – %s (%s). Map menu » \"Last rare enemy\" sets the pin.",
    RARE_SOURCE_unit = "seen: enemy near you",
    RARE_SOURCE_vignette = "seen: Blizzard's minimap",
    RARE_SOURCE_preview = "sample",
    RARE_PREVIEW_NAME = "Sample enemy",
    RARE_NO_POSITION = "position unknown",
    RARE_NONE = "No rare enemy has been reported in this session yet.",
    RARE_LAST_NO_POSITION = "No position is known for \"%s\".",
    MENU_RARE_LAST = "Last rare enemy – waypoint: %s",
    STATUS_RARES_ON = "Rare enemies: alert on (chat line when one comes into view).",
    STATUS_RARES_OFF = "Rare enemies: alert off.",
    STATUS_RARES_OTHER = "Rare enemies: %s is running, so ezMap holds back. Report anyway:",
    STATUS_RARES_ALSO = "The alert has to be on as well:",
    STATUS_RARES_DESPITE = "(despite %s – alerts may come twice)",
    OPT_HEADER_RARES = "Rare enemies",
    OPT_HEADER_RARES_TIP = "Explorer knowledge is shown only on request, so the alert is off by default. ezMap ships no list of rare enemies: it only reports what the game itself is showing right now (an enemy with a silver dragon near you or its icon on Blizzard's minimap). On the map it only draws where you have seen one yourself – and only with \"Seen rare enemies on the map\" in the tree \"Map: what to show\" (group \"Treasures and explorer knowledge\"). While an addon that reports rare enemies itself is running (e.g. RareScanner), ezMap stays quiet – unless \"Also report while RareScanner or similar is running\" is ticked.",
    OPT_rareAlert = "Rare enemy alert",
    OPT_rareAlert_TIP = "What you get: you never walk past a rare enemy. When one comes into view (nameplate, mouseover, target or its icon on Blizzard's minimap), ezMap writes a chat line with name, zone and coordinates; in the map menu \"Last rare enemy\" sets the pin there. No report during combat, at most every ten minutes per enemy. Off by default.",
    OPT_rareSound = "Sound with the alert",
    OPT_rareOverride = "Also report while RareScanner or similar is running",
    OPT_rareOverride_TIP = "While an addon that reports rare enemies itself is running (e.g. RareScanner, SilverDragon, NovaRares or Tweaks Forever with its alert switched on), ezMap stays quiet by default – otherwise every alert would come twice. For RareScanner ezMap only sees that it is running, not its own switches. This tick only works together with \"Rare enemy alert\" (chat line) or \"Seen rare enemies on the map\" (map icons): then ezMap reports anyway or draws remembered sightings on the map. This also applies while an addon only draws rare enemies on the map without reporting them (e.g. HandyNotes: WoW Forever): the same tick brings ezMap's map icons back.",
    OPT_rareSound_TIP = "What you get: you hear the alert even when you are not looking at the chat (Blizzard's raid warning, once per report). Only with \"Rare enemy alert\".",
    OPT_RARE_PREVIEW = "Alert – sample",
    OPT_RARE_PREVIEW_TIP = "Writes a sample report to the chat and plays the sound – this is how the alert looks and sounds.",
    OPT_RARE_LAST = "Last rare enemy",
    OPT_RARE_LAST_TIP = "Sets Blizzard's pin on the rare enemy reported last (as in the map menu and /ezmap rare).",
    -- Map tree (Tree.lua, user request of 15.11.2026)
    OPT_HEADER_TREE = "Map: what to show",
    OPT_HEADER_TREE_TIP = "Everything ezMap shows on Blizzard's world map, on the minimap and in the map menus, as a tree: \"Everything\" at the top, groups below, single kinds below those. A group switches everything below it; if the kinds are mixed it shows \"Partly\" – choosing \"Partly\" again brings back the last mixed selection. Every check box stays remembered on its own. The same outline is in the ezMap button on the world map (\"What ezMap shows on the map\", gathering in its own section).",
    OPT_tree_all = "Everything from ezMap",
    OPT_tree_all_TIP = "What you get: one switch hides everything ezMap shows on the map, the minimap and in the map menus – and shows it again. \"Partly\" means some things are on and some off; choosing it brings back your last mixed selection. In the map menu one click hides everything, the next brings back the state before; explorer knowledge only comes back on if it was on before.",
    OPT_tree_trainers = "Trainers",
    OPT_tree_trainers_TIP = "What you get: you find your trainer again when new ranks are waiting. Every trainer whose window you open is remembered (in ezCore, for all ez modules); in the map menu and in the \"Tracking\" menu a click under \"Trainers\" sets the pin to them. Below, one by one: class trainers, pet trainers, profession trainers per profession, other trainers. Off: ezMap offers no trainers – they stay remembered.",
    OPT_tree_trainerProf = "Profession trainers",
    OPT_tree_trainerProf_TIP = "What you get: show or hide profession trainers per profession. A profession appears here once you have visited one of its trainers (one by one in the ezMap button; new professions follow this choice).",
    OPT_trainerClass = "Class trainers",
    OPT_trainerClass_TIP = "What you get: trainers of your class are listed under \"Trainers\" in the map menu, plus \"Nearest class trainer\" on your continent. Source: trainers whose window you opened (ezCore).",
    OPT_trainerPet = "Pet trainers",
    OPT_trainerPet_TIP = "What you get: pet trainers (hunters learn their pet's abilities there) are listed under \"Trainers\", and for hunters \"Nearest pet trainer\". Source: visited trainers (ezCore).",
    OPT_trainerOther = "Other trainers",
