    OPT_repairTargets = "Vendors who repair",
    OPT_repairTargets_TIP = "What you get: vendors who can repair your gear as destinations in the map menu – even when the other vendors are off. Source: visited vendors (ezCore).",
    OPT_tree_travel = "Travel and flight masters",
    OPT_tree_travel_TIP = "What you get: the nearest flight master in the \"Tracking\" menu, the flight master at your pin's destination with the learned flight time, the flight time in the tooltip of flight points, the bar with the remaining time while flying and the flight points you or your alts are still missing.",
    OPT_flightNearest = "Nearest flight master",
