    OPT_flightDest = "Flight master at the destination",
    OPT_flightDest_TIP = "What you get: with a pin set, the map menu and the \"Tracking\" menu name the flight master at the destination and the flight time there if you have flown that route before (\"measured by you\"). No route planner.",
    -- Flight points you or your alts are missing (wave 26, F5; FlightNodes.lua)
    OPT_flightMissing = "Missing flight points (alts too)",
    OPT_flightMissing_TIP = "What you get: the map menu lists \"Flight points you're missing\" for the continent of the shown map, below that each alt's missing ones; a click sets Blizzard's map pin. The tooltip of Blizzard's flight points on the world map names the alts that haven't discovered it yet. Source: which flight points exist, according to the client tables (ezCore); what a character knows, according to Blizzard's flight map and world map, read at login and at the flight master.",
    MENU_TAXI = "Flight points you're missing",
    MENU_TAXI_COUNT = "Flight points you're missing (%d)",
