    OPT_entranceList = "Entrances in the map menu",
    OPT_entranceList_TIP = "What you get: under \"Dungeon entrances\" in the map menu and in the \"Tracking\" menu a click sets the pin to the entrance – even if another addon draws the icons. Same source as the icons.",
    OPT_tree_gather = "Gathering",
    OPT_tree_gather_TIP = "What you get: your own spots for herbs, ores and fishing on the world map (source: your harvests, remembered by ezCore). Below, one by one per kind; \"When to show\" and single nodes are on the kind in the ezMap button under \"Gathering spots\", size and opacity under \"Gathering\".",
    OPT_tree_explorer = "Treasures and explorer knowledge",
    OPT_tree_explorer_TIP = "What you get: knowledge for exploring – chests, spots of missing library books, rare enemies you have seen – only when you want it (explorer knowledge is off by default). Source: what you saw yourself (ezCore), for books otherwise Questie when it runs.",
    OPT_tree_own = "Own waypoints and map helpers",
    OPT_tree_own_TIP = "What you get: the pins you set last in the map menu (\"Recent\") and the coordinates line on the world map.",
    -- Topics of the map menu (wave 27)
    OPT_tree_town = "Services in town",
    OPT_tree_town_TIP = "What you get: trainers, vendors and recipe spots in one place – everything you look for in towns and villages. The icons are the same as in Blizzard's minimap \"Tracking\" menu (trainers, vendors, repair …): Blizzard's list shows these services on the minimap, ezMap sets the map pin to the ones you visited from the map menu.",
    OPT_tree_discover = "Discover",
    OPT_tree_discover_TIP = "What you get: knowledge for discovering – chests, library books, rare enemies you saw and, while Questie runs, enemies and objects according to Questie. Only on request: \"Everything from ezMap\" does not turn this topic on. Clicking \"Discover\" itself turns explorer knowledge on; the group \"according to Questie\" needs its own tick, and inside it objects and rare enemies each need their own as well.",
    OPT_tree_journey = "Journey",
    OPT_tree_journey_TIP = "What you get: flight masters, flight times, flight points you or your alts still miss, and dungeon entrances in one place.",
