    TREE_ALL_ON_TIP = "Turns on every entry of this group. The choice is remembered.",
    TREE_ALL_ON_TIP_SKIP = "Turns on every entry of this group except %s – that only comes on with its own tick (only on request). The choice is remembered.",
    TREE_ALL_OFF_TIP = "Turns off every entry of this group. The choice is remembered; clicking the group itself brings back the state before.",
    MSEC_WAY = "Map pins",
    MSEC_SHOW = "Shown on the map",
    TRACK_SEC_MINIMAP = "Minimap",
    TRACK_SEC_TOWN_TIP = "Blizzard's list above shows these services on the minimap; ezMap sets the map pin to the trainers you visited – with the same icons as Blizzard's entries. If Blizzard's matching entry is listed above, ezMap's entry sits right below it; with \"Switch together with Blizzard's tracking\" both switch together.",
    OPT_wayRecent = "Recently set pins",
    OPT_wayRecent_TIP = "What you get: under \"Recent\" in the map menu and in the \"Tracking\" menu a click sets an earlier pin again (like /way list).",
    OPT_mapPlace = "ezMap on the world map",
    OPT_mapPlace_TIP = "What you get: everything ezMap does with one click on the map. \"Button\" (default): a round button next to Blizzard's map pin button – left-click opens a menu in sections (map pins, services in town, journey, gathering, discover, what ezMap shows on the map), right-click the settings. \"Blizzard's map filter\": no button of its own, ezMap's switches are in Blizzard's map filter (button at the top right of the world map), section \"ezMap\". \"Both\": the button and the section in the map filter – the button then points to the map filter for the tree and the gathering spots.",
    MAP_PLACE_button = "Button",
