    TREE_MENU = "What ezMap shows on the map",
    TREE_MENU_TIP = "The same tree as in the settings (\"Map: what to show\"): show or hide everything, groups and single kinds. Gathering has its own section above (\"Gathering spots\").",
    MENU_VENDORS = "Vendors here (%d)",
    MENU_VENDORS_TIP = "Vendors in this zone you have already talked to (ezCore remembers them). A click sets Blizzard's map pin.",
