    VENDOR_REPAIR_MARK = "(repair)",
    STATUS_TREE = "Map (tree): off: %s; partly: %s.",
    STATUS_TREE_NONE = "nothing",
    -- Gathering spots on the minimap (SAM-11)
    OPT_tree_gatherMini = "On the minimap",
    OPT_tree_gatherMini_TIP = "What you get: your own spots also appear on Blizzard's minimap once you are in range – per kind, by the rule \"When to show\" for the minimap (by default herbs and ores only while tracking, fishing never). Hovering shows the same tooltip as on the world map; a click goes to the minimap (ping). Source: your harvests (ezCore).",
    OPT_gatherMiniHerb = "Herbs on the minimap",
    OPT_gatherMiniHerb_TIP = "What you get: spots of herbs you have harvested, on the minimap in range. \"When to show\" decides when they appear (by default: while herb tracking is on).",
    OPT_gatherMiniOre = "Ores on the minimap",
    OPT_gatherMiniOre_TIP = "What you get: spots of ores you have mined, on the minimap in range. \"When to show\" decides when they appear (by default: while mineral tracking is on).",
    OPT_gatherMiniFish = "Fishing spots on the minimap",
    OPT_gatherMiniFish_TIP = "What you get: places where you have fished, on the minimap in range – by default as soon as you can fish (rule \"With profession\", change it under \"When to show\").",
    OPT_tree_gatherColor = "By colour (skill point)",
    OPT_tree_gatherColor_TIP = "What you get: only the nodes that give you a skill point with the chance you choose – on the world map, the minimap and in routes. ezCollection calculates the colour from your skill and the skill the node needs (from the client message or seen by you) by the rule of thumb for gathering professions: orange up to %ORANGE_TO%, yellow up to %YELLOW_TO%, green up to %GREEN_TO% points above it, grey after that. Calculated, not reported by the game. This filter does not count towards \"Gathering\" and \"Everything from ezMap\" and is not switched by their click. Nodes you cannot gather yet (red) are shown reddish and fainter – untick \"Red – cannot gather yet\" to hide them. Chests and fishing spots are not sifted by colour.",
    OPT_gatherColorOrange = "Orange – certain skill point",
    OPT_gatherColorOrange_TIP = "What you get: nodes that give you a skill point on every harvest (your skill is at most %ORANGE_TO% points above the skill needed; calculated).",
    OPT_gatherColorYellow = "Yellow – usually a point",
    OPT_gatherColorYellow_TIP = "What you get: nodes with a high chance of a skill point (%YELLOW_FROM% to %YELLOW_TO% points above the skill needed; the chance falls evenly from %YELLOW_PCT_FROM% to about %YELLOW_PCT_TO%, the tooltip on the spot names it; calculated).",
    OPT_gatherColorGreen = "Green – falling chance",
    OPT_gatherColorGreen_TIP = "What you get: nodes whose chance of a skill point keeps falling (%GREEN_FROM% to %GREEN_TO% points above the skill needed; from about %GREEN_PCT_FROM% to about %GREEN_PCT_TO%, the tooltip on the spot names it; calculated).",
    OPT_gatherColorGray = "Grey – no point any more",
    OPT_gatherColorGray_TIP = "What you get: nodes that no longer give you a skill point (%GRAY_FROM% points or more above the skill needed) – only for the yield.",
    OPT_gatherColorRed = "Red – cannot gather yet",
    OPT_gatherColorRed_TIP = "What you get: herbs and ores your skill is not high enough for yet according to ezCore (from the client message or seen by you), or whose profession you lack – reddish and fainter, so you see what comes later. Unticked, ezMap hides them (formerly the tick \"Only what I can gather\"). Nodes without a known skill stay visible.",
    OPT_gatherColorUnknown = "Unknown",
    OPT_gatherColorUnknown_TIP = "What you get: nodes whose needed skill ezCollection does not know yet (it learns it as you gather) or only knows from above and that lies above your skill, and all nodes while your own skill is unknown. This filter does not sift fishing spots (they need no skill, the chance depends on the zone) – hide those with the tick \"Fishing spots\". Blizzard has no white stage for skill points (only orange, yellow, green, grey); \"unknown\" takes its place here.",
    OPT_gatherMiniChest = "Chests on the minimap",
    OPT_gatherMiniChest_TIP = "What you get: chests you have opened, on the minimap in range. Explorer knowledge: off by default.",
    OPT_gatherMiniMode = "%s on the minimap: when to show",
    OPT_gatherMiniMode_TIP = "When ezMap shows the spots of %s on the minimap: always, only with the matching profession or only while the matching tracking in the minimap's tracking menu is on. To hide them completely, untick the kind. Stored in ezCore (minimap surface, separate from the world map).",
    OPT_gatherMiniSize = "Size on the minimap",
    OPT_gatherMiniSize_TIP = "How large (in pixels) ezMap draws the spots on the minimap.",
    OPT_gatherMiniAlpha = "Opacity on the minimap",
    OPT_gatherMiniAlpha_TIP = "How opaque the spots on the minimap are. Less lets Blizzard's minimap show through.",
    OPT_gatherHideNearYards = "Hide nearby on the minimap",
    OPT_gatherHideNearYards_TIP = "When you get closer to a remembered spot than the set distance (in yards), ezMap's dot on the minimap disappears – so it does not cover Blizzard's own tracking symbol (Find Herbs, Find Minerals …) and you can see whether the node is really there right now. Walk farther away and the dot comes back. All the way left (\"off\") every dot stays. This also applies to the large “next point” of a gathering route and its dots at spots; the small dots in between keep showing the direction. The minimap shows Blizzard's symbol only while the matching tracking is active in the minimap's tracking menu. The further the minimap is zoomed in, the more of its area lies within this radius. The world map stays as it is (Blizzard shows no nodes there). Source of the distance: your position as reported by the game.",
    GMAP_MINI_SEARCH = "Only while tracking",
    GMAP_MINI_GROUP = "Gathering spots on the minimap",
    GMAP_MINI_CHEST = "Chests on the minimap (explorer knowledge)",
    GMAP_MINI_CHEST_NOTE = "Chests are explorer knowledge (only on request), so they are not part of the group \"Gathering spots on the minimap\" – its checkbox does not switch them.",
    GMAP_MINI_SEARCH_TIP = "On: herbs and ores appear on the minimap only while herb or mineral tracking at the top of this menu is on. Off: back to what it was before (without an earlier choice: with the matching profession). Fine-tune per kind under \"Gathering spots on the minimap\", submenu of the kind.",
    GMAP_MINI_WHEN_TIP = "Rule for this kind on the minimap (separate from the world map). It applies only while the kind's tick is set.",
    GMAP_MINI_UNAVAILABLE_api = "Not possible right now: the client does not tell the minimap's view radius (C_Minimap.GetViewRadius is missing), so ezCore places no dots there. The spots stay on the world map.",
    GMAP_MINI_UNAVAILABLE_nocore = "Not possible right now: ezCore brings no dots for the minimap (too old).",
    GMAP_MINI_STATE = "On the minimap: %d of %d spots in range",
    GMAP_MINI_OFF = "Minimap without dots right now: %s",
    GMAP_MINI_STATE_TIP = "State from ezCore: how many of your spots in this zone are in the minimap's range right now, or why none are shown there.",
    GMAP_MINI_WHY_off = "no kind switched on",
    GMAP_MINI_WHY_other = "a gathering addon draws",
    GMAP_MINI_WHY_api = "the client does not tell the view radius",
    GMAP_MINI_WHY_nocore = "ezCore without the dot layer",
    STATUS_GATHER_MINI = "Minimap: %s.",
    STATUS_GATHER_MINI_OFF = "Minimap: off (%s).",
    -- One layer for all spots (SAM-22)
    OPT_rarePins = "Seen rare enemies on the map",
    OPT_rarePins_TIP = "What you get: wherever you have seen a rare enemy, the world map shows an icon – tooltip \"seen by you on …\", a click sets the pin. Source: your own sightings (ezCore remembers them). Explorer knowledge: off by default. What Blizzard currently shows as an icon itself, ezMap does not draw twice; while an addon already draws rare enemies on the map (e.g. RareScanner, SilverDragon or HandyNotes: WoW Forever), ezMap stays out of it – unless \"Also report while RareScanner or similar is running\" under \"Rare enemies\" is ticked.",
    OPT_bookPins = "Spots of missing books on the map",
    OPT_bookPins_TIP = "What you get: the spots of library books this character has not handed in yet are shown as dots on the zone's world map (the same as in the \"Library books\" submenu); a click sets the pin. Source: where you picked the book up, otherwise according to Questie (when it runs). Explorer knowledge: off by default. If HandyNotes – Forever Books already draws the books, ezMap stays out of it.",
    RAREPIN_SEEN = "seen by you on %s",
