    BOOKPIN_KIND = "Library book, not handed in yet",
    BOOKPIN_HINT = "Click: set Blizzard's map pin",
    STATUS_RAREPINS_ON = "Seen rare enemies on the map: on.",
    STATUS_RAREPINS_OFF = "Seen rare enemies on the map: off.",
    STATUS_RAREPINS_OTHER = "Seen rare enemies on the map: on, but %s draws rare enemies – ezMap stays out of it.",
    -- Enemies and objects according to Questie (wave 27, F5 b; QuestieSpawns.lua)
    OPT_tree_questie = "Enemies and objects according to Questie",
    OPT_tree_questie_TIP = "What you get: every spawn of enemies and objects in the zone shown, as Questie knows them, as dots on the world map – filterable by name, quest, item and rank (in this group's submenu). Only on request: neither \"All\" nor \"Discover\" switch the group on, and its tick does not switch \"Objects\" and \"Rare enemies\" along (each has its own tick). Source: Questie (QuestieDB, read only, nothing stored). Reading starts only when you switch the group on and show a zone; the first time takes a few seconds. Needs Questie (or QuestieDB alone); without it the group stays here only, not on the map.",
    OPT_questieNpcs = "Enemies",
    OPT_questieNpcs_TIP = "What you get: where enemies and other NPCs of the zone stand (yellow dots, elites and bosses red). Source: according to Questie. Clicking a dot sets Blizzard's map pin.",
    OPT_questieObjects = "Objects",
    OPT_questieObjects_TIP = "What you get: where objects of the zone are – quest objects, herbs, ore veins, chests (green dots). Questie does not separate treasures from other objects – so only with their own tick, like rare enemies: \"Check All\" and the group's tick leave them out. Source: according to Questie.",
    OPT_questieRares = "Rare enemies (explorer knowledge)",
    OPT_questieRares_TIP = "What you get: the spawns of rare enemies according to Questie as well (skull icon). Explorer knowledge: only on explicit request – no group above switches it on. Without \"Enemies\" this tick shows only the rares. ezCore's \"Show explorer knowledge\" shows them too, together with \"Enemies\".",
    OPT_tree_questieRank = "By rank",
    OPT_tree_questieRank_TIP = "What you get: sift enemies by their rank according to Questie – normal, elites and bosses. Unticking hides those enemies; objects have no rank and stay. Rare enemies are controlled only by the tick \"Rare enemies (explorer knowledge)\".",
    OPT_questieRankNormal = "Normal enemies",
    OPT_questieRankNormal_TIP = "Show enemies without an elite rank (according to Questie).",
    OPT_questieRankElite = "Elites and bosses",
    OPT_questieRankElite_TIP = "Show elite enemies and bosses (according to Questie).",
