    QSPAWN_STATE_OFF_TIP = "Tick \"Enemies\", \"Objects\" or \"Rare enemies\", then ezCore reads the zone shown from Questie.",
    QSPAWN_COUNT = "Here according to Questie: %d |4enemy:enemies;, %d |4object:objects;",
    QSPAWN_COUNT_TIP = "Counted after your filters (kinds, rank, name, quest, item). Source: Questie (QuestieDB, read only).",
    QSPAWN_HIDDEN_RARE = "%d rare |4enemy:enemies; hidden (explorer knowledge: tick \"Rare enemies\").",
