-- Grenzen der Farben beim Sammeln (Teilwelle 15b) aus ezCore einsetzen – eine Quelle: Core.Gathering.SKILL_STEPS und
-- Core.Gathering.SkillUpChance. Weicht Forever ab, ändert sich nur ezCore; die Texte hier ziehen mit.
-- Platzhalter wie %CMD%: %ORANGE_TO%, %YELLOW_FROM%, %YELLOW_TO%, %GREEN_FROM%, %GREEN_TO%, %GRAY_FROM%,
-- %YELLOW_PCT_FROM%, %YELLOW_PCT_TO%, %GREEN_PCT_FROM%, %GREEN_PCT_TO%
function ns.FillSkillSteps(lang, G)
    local steps = type(G) == "table" and type(G.SKILL_STEPS) == "table" and G.SKILL_STEPS or nil
    if not (steps and type(G.SkillUpChance) == "function") then return lang end
    local y, g, gray = steps.yellow, steps.green, steps.gray
    local function Pct(rank) return ezCore.Percent(math.floor((G.SkillUpChance(rank, y, gray) or 0) * 100 + 0.5)) end
    local values = { ORANGE_TO = y - 1, YELLOW_FROM = y, YELLOW_TO = g - 1, GREEN_FROM = g, GREEN_TO = gray - 1,
        GRAY_FROM = gray, YELLOW_PCT_FROM = Pct(y), YELLOW_PCT_TO = Pct(g - 1), GREEN_PCT_FROM = Pct(g),
        GREEN_PCT_TO = Pct(gray - 1) }
    for key, text in pairs(lang) do
        if type(text) == "string" and text:find("%", 1, true) then
            lang[key] = text:gsub("%%([%u_]+)%%", function(name)
                local v = values[name]
                return v ~= nil and tostring(v) or nil
            end)
        end
    end
    return lang
end
ns.FillSkillSteps(de, ezCore.Gathering)
ns.FillSkillSteps(en, ezCore.Gathering)

ns.isGerman = ezCore.IsGerman()
ns.L = ezCore.NewLocale(de, en, ezCore.L)
ns.LOCALES = { de = de, en = en }    -- für die Tests: beide Sprachen gleich vollständig
